package com.tihai.controller;
import com.tihai.utils.*;import com.tihai.common.*;import com.tihai.dubbo.pojo.course.Course;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.context.ApplicationContext;import java.util.*;import java.util.concurrent.*;import okhttp3.OkHttpClient;import okhttp3.HttpUrl;
@RestController @RequestMapping("/local/review") public class ReviewController {
 @Autowired private AccountRegistry registry;@Autowired private ReviewStore store;@Autowired private ReviewReferenceService referencesService;@Autowired private JdbcTemplate db;@Autowired private ApplicationContext context;@Autowired private AssessmentController assessments;
 private final Map<String,Future<?>> scans=new ConcurrentHashMap<>();private final ExecutorService executor=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"review-read-only-collector");t.setDaemon(true);return t;});
 @javax.annotation.PostConstruct public void recoverCoverage()throws Exception{for(Map<String,Object> c:store.courses()){Map<String,Object> state=(Map<String,Object>)c.get("coverage");if(state!=null&&"running".equals(state.get("state"))){state.put("state","partial");state.put("message","上次收录因后台关闭中断，已读取内容保留，请重新更新");store.coverage(String.valueOf(c.get("id")),state);}}}
 @javax.annotation.PreDestroy public void shutdown(){executor.shutdownNow();}
 @GetMapping("/courses") public R courses()throws Exception{for(Map<String,Object> t:db.queryForList("SELECT id,course_name FROM th_wk_queue"))store.course(String.valueOf(t.get("id")),String.valueOf(t.get("course_name")));List<Map<String,Object>> rows=store.courses();if(registry!=null)rows.removeIf(r->!registry.ownsTask(String.valueOf(r.get("id"))));for(Map<String,Object> row:rows)row.put("collecting",scans.containsKey(row.get("id"))&&!scans.get(row.get("id")).isDone());return R.ok().setData(rows);}
 @PostMapping("/collect") public synchronized R collect(@RequestBody Map<String,String> body)throws Exception{String id=body.get("course");List<Map<String,Object>> rows=db.queryForList("SELECT login_account,course_id,course_name FROM th_wk_queue WHERE id=?",id);if(rows.isEmpty())return R.error(404,"课程任务已移除，可继续使用历史题库，但不能更新来源");if(scans.containsKey(id)&&!scans.get(id).isDone())return R.error(409,"该课程正在收录");Map<String,Object> row=rows.get(0);store.course(id,String.valueOf(row.get("course_name")));scans.put(id,executor.submit(()->scan(id,row)));return R.ok("已开始只读收录，不播放视频、不答题、不交卷");}
 private void scan(String id,Map<String,Object> row){Map<String,Object> state=new LinkedHashMap<>();state.put("state","running");state.put("processed",0);state.put("total",0);state.put("message","正在读取课程；考试题目未接入");List<String> errors=new ArrayList<>();
  try{store.coverage(id,state);String account=String.valueOf(row.get("login_account")),courseId=String.valueOf(row.get("course_id"));String cookies=db.queryForObject("SELECT cookies FROM th_wk_user WHERE account=? LIMIT 1",String.class,account);CourseUtil u=new CourseUtil();context.getAutowireCapableBeanFactory().autowireBean(u);u.setAccount(account);u.setCookies(cookies);Course course=u.getCourseList().stream().filter(c->courseId.equals(c.getCourseId())).findFirst().orElseThrow(()->new IllegalStateException("登录已失效"));OkHttpClient http=u.initSession(false,false).newBuilder().callTimeout(45,TimeUnit.SECONDS).build();
   List<ChapterPoint> chapters=new ArrayList<>();for(CoursePoint group:u.getCoursePoint(courseId,course.getClazzId(),course.getCpi()))if(group.getPoints()!=null)chapters.addAll(group.getPoints());if(chapters.isEmpty())throw new IllegalStateException("章节目录为空");state.put("total",chapters.size());
   int index=0;for(ChapterPoint chapter:chapters){if(Thread.currentThread().isInterrupted())throw new InterruptedException();try{
    Pair<List<Job>,List<JobInfo>> jobs=u.getReviewJobList(course.getClazzId(),courseId,course.getCpi(),chapter.getId());if(!jobs.getSecond().isEmpty()&&Boolean.TRUE.equals(jobs.getSecond().get(0).getNotOpen()))throw new IllegalStateException("章节未开放");
    for(Job job:jobs.getFirst())if("workid".equals(job.getType())){JobInfo info=job.getCardInfo();HttpUrl url=HttpUrl.parse("https://mooc1.chaoxing.com/mooc-ans/api/work").newBuilder().addQueryParameter("api","1").addQueryParameter("workId",job.getJobId().replace("work-","")).addQueryParameter("jobid",job.getJobId()).addQueryParameter("originJobId",job.getJobId()).addQueryParameter("needRedirect","true").addQueryParameter("skipHeader","true").addQueryParameter("knowledgeid",info.getKnowledgeid()).addQueryParameter("ktoken",info.getKtoken()).addQueryParameter("cpi",info.getCpi()).addQueryParameter("ut","s").addQueryParameter("clazzId",course.getClazzId()).addQueryParameter("enc",job.getEnc()).addQueryParameter("mooc2","1").addQueryParameter("courseid",courseId).build();List<Map<String,Object>> qs=ReviewParser.read(AssessmentController.get(http,url.toString()));if(qs.isEmpty())throw new IllegalStateException("测验题目未读取到");store.add(id,"章节小测",chapter.getTitle()+" / "+job.getTitle(),chapter.getId()+"|"+job.getJobId(),qs,index);}
   }catch(Exception e){errors.add("第"+(index+1)+"章未完整读取");}state.put("processed",++index);state.put("message","已检查 "+index+" / "+chapters.size()+" 章；读取失败 "+errors.size()+" 项；考试未收录");store.coverage(id,state);Thread.sleep(120);}
   try{int n=0;for(Map<String,String> work:assessments.reviewWorkLinks(account,courseId)){List<Map<String,Object>> qs=ReviewParser.read(AssessmentController.get(http,work.get("url")));if(qs.isEmpty()){errors.add("独立作业未读取到题目");continue;}store.add(id,"作业",work.get("title"),work.get("id"),qs,n++);}}catch(Exception e){errors.add("独立作业列表或题目未完整读取");}
   state.put("state",errors.isEmpty()?"finished":"partial");state.put("message","本轮读取结束；未完整读取 "+errors.size()+" 项；考试读题尚未接入，未收录");
  }catch(Exception e){state.put("state","partial");state.put("message","读取中断或登录失效；已收录题目保留，考试未收录");}finally{state.put("errors",errors);state.put("updatedAt",java.time.LocalDateTime.now().toString());try{store.coverage(id,state);}catch(Exception ignored){}}
 }
 @GetMapping("/questions") public R questions(@RequestParam String course,@RequestParam(defaultValue="false")boolean wrong,@RequestParam(defaultValue="false")boolean practice,@RequestParam(defaultValue="false")boolean references){List<Map<String,Object>> qs=store.questions(course,wrong);if(practice){qs.removeIf(q->!Boolean.TRUE.equals(q.get("gradeable"))&&!(references&&ReviewStore.eligible(q)));for(Map<String,Object> q:qs){q.remove("platformAnswer");q.remove("canonicalAnswer");q.remove("studentAnswer");q.remove("explanation");q.remove("referenceAnswer");q.remove("referenceCanonical");}}return R.ok().setData(qs);}
 @PostMapping("/check") public R check(@RequestBody Map<String,String> body){try{boolean allow=Boolean.parseBoolean(body.getOrDefault("allowReference","false"));Map<String,Object> question=store.question(body.get("course"),body.get("id"));ReviewParser.canonical((String)question.get("type"),body.getOrDefault("answer",""),(List<String>)question.get("options"));if(allow)referencesService.ensure(body.get("course"),body.get("id"));return R.ok().setData(store.check(body.get("course"),body.get("id"),body.getOrDefault("answer",""),allow));}catch(Exception e){return R.error(400,"判分失败：请检查作答格式、题库或 AI 配置；参考答案可能暂不可用，未标记错题");}}
 @PostMapping("/reference") public R reference(@RequestBody Map<String,String> body){if(!Boolean.parseBoolean(body.getOrDefault("allowReference","false")))return R.error(400,"需要明确允许参考答案查询");try{referencesService.ensure(body.get("course"),body.get("id"));Map<String,Object> q=store.question(body.get("course"),body.get("id"));Map<String,Object> data=new LinkedHashMap<>();data.put("available",Boolean.TRUE.equals(q.get("gradeable"))||Boolean.TRUE.equals(q.get("referenceAvailable")));data.put("source",Boolean.TRUE.equals(q.get("gradeable"))?"平台公布答案":q.get("referenceSource"));return R.ok().setData(data);}catch(Exception e){return R.error(400,"参考答案暂不可用，请检查题库和 AI 配置");}}
 @PostMapping("/export") public R export(@RequestBody Map<String,String> body){try{String course=body.get("course"),format=body.getOrDefault("format","docx");Map<String,Object> snapshot=store.snapshot(course);if(((List)snapshot.get("questions")).isEmpty())return R.error(400,"题库为空，请先收录题目");boolean self="self".equals(body.get("mode"));byte[] bytes="json".equals(format)?new com.fasterxml.jackson.databind.ObjectMapper().writerWithDefaultPrettyPrinter().writeValueAsBytes(snapshot):ReviewDocx.create(snapshot,self);Map<String,Object> data=new LinkedHashMap<>();data.put("fileBase64",Base64.getEncoder().encodeToString(bytes));data.put("extension","json".equals(format)?"json":"docx");return R.ok().setData(data);}catch(Exception e){return R.error(500,"导出失败，请检查本机题库文件");}}
}
